from pathlib import Path
root=Path('dist')
(root/'index.html').write_text('''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ML VLAB | Gradient Descent</title><link rel="stylesheet" href="vendor/katex/katex.min.css"><link rel="stylesheet" href="style.css"></head>
<body><aside><a class="brand" href="#aim"><img class="brand-image" src="assets/vesit-logo.jpg" alt="Vivekanand Education Society Institute of Technology (Autonomous)"><span>ML VLAB</span></a><p class="sidebar-description">Machine Learning Virtual Laboratory</p><div class="nav-label">Experiment 1</div><nav id="nav" aria-label="Experiment sections"></nav></aside><div class="workspace"><header aria-label="Breadcrumb">Machine Learning <span>›</span> Optimization <span>›</span> Experiment 1</header><main id="main"></main><footer><strong>ML VLAB</strong><span>Made by Riddhi Tamhankar and Niharika pawar</span><span>VESIT · Machine Learning</span></footer></div><script src="vendor/katex/katex.min.js"></script><script src="app.js"></script></body></html>''',encoding='utf-8')
p=root/'app.js';s=p.read_text(encoding='utf-8')
start=s.index("document.querySelector('#nav').innerHTML")
end=s.index('function render()')
s=s[:start]+r'''document.querySelector('#nav').innerHTML=pages.map(p=>`<a href="#${p.toLowerCase()}" data-page="${p.toLowerCase()}">${p}</a>`).join('');
const intro=(label,title,sub)=>`<div class="experiment-title">Experiment 1: Gradient Descent</div><h1>${title}</h1><p class="subtitle">${sub}</p>`;
const bottom=(prev,next)=>`<div class="bottom-nav"><span>${prev?`<a href="#${prev.toLowerCase()}">← ${prev}</a>`:''}</span>${next?`<a href="#${next.toLowerCase()}">Next: ${next} →</a>`:''}</div>`;
function illustration(){
const X=t=>64+(t+3)*78,Y=j=>230-j*19;
const f=t=>0.8*t*t+0.5;
const samples=Array.from({length:121},(_,i)=>-3+i*.05);
const steps=[-2.8,-1.95,-1.35,-.92,-.61,-.39,-.23];
const curve=samples.map((t,i)=>`${i?'L':'M'}${X(t).toFixed(2)},${Y(f(t)).toFixed(2)}`).join(' ');
return `<svg viewBox="0 0 600 290" role="img" aria-labelledby="plot-title plot-desc"><title id="plot-title">Gradient descent on a convex loss function</title><desc id="plot-desc">A quadratic loss with a minimum at theta zero. Arrows connect gradient descent iterates approaching the minimum from the left.</desc><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#8b1a1a" stroke-width="1"/></marker></defs><rect width="600" height="290" fill="white"/><g fill="none" stroke="#333" stroke-width="1"><path d="M64 35V230H545"/>${[-3,-2,-1,0,1,2,3].map(t=>`<path d="M${X(t)} 230v5"/>`).join('')}${[0,2,4,6,8].map(j=>`<path d="M59 ${Y(j)}h5"/>`).join('')}</g><g fill="#444" font-size="12" font-family="system-ui">${[-3,-2,-1,0,1,2,3].map(t=>`<text x="${X(t)}" y="251" text-anchor="middle">${t}</text>`).join('')}${[0,2,4,6,8].map(j=>`<text x="50" y="${Y(j)+4}" text-anchor="end">${j}</text>`).join('')}</g><path d="${curve}" fill="none" stroke="#333" stroke-width="1.7"/>${steps.slice(0,-1).map((t,i)=>`<path d="M${X(t)+4} ${Y(f(t))+3}L${X(steps[i+1])-5} ${Y(f(steps[i+1]))-3}" stroke="#8b1a1a" stroke-width="1.1" fill="none" marker-end="url(#arrow)"/>`).join('')}${steps.map(t=>`<circle cx="${X(t)}" cy="${Y(f(t))}" r="3" fill="#8b1a1a"/>`).join('')}<g fill="#1a1a1a" font-size="17" font-family="Georgia,serif"><text x="298" y="278" text-anchor="middle">θ</text><text x="21" y="134" transform="rotate(-90 21 134)" text-anchor="middle">J(θ)</text></g></svg>`}
function aimPage(){return intro('','Aim','To implement gradient descent on a real dataset and study how the learning rate affects convergence and optimization performance.')+`<div class="equation"><div id="aim-equation" aria-label="theta is updated to theta minus alpha times the gradient of J of theta">θ := θ − α ∇J(θ)</div><span>(1)</span></div><figure class="academic-figure">${illustration()}<figcaption>Figure 1: Gradient descent on a convex loss function</figcaption></figure><details class="experiment-reference"><summary>Experiment details and learning objectives</summary><p>Estimated time: 25–35 minutes. Level: beginner. Model: linear regression.</p><ul><li>Connect gradients, parameter updates, and the loss function to understand model learning.</li><li>Explore slow progress, stable convergence, and divergence by changing the learning rate.</li><li>Compare loss, iterations, and prediction error against a least-squares benchmark.</li></ul><p>Kaggle Advertising: 200 observations. Input: TV advertising spend. Target: Sales.</p><p><a href="${source}" target="_blank" rel="noreferrer">View Kaggle dataset</a> · <a href="#demo">Open experiment</a></p></details>`+bottom(null,'Theory')}
''' +s[end:]
start=s.index("if(page==='aim')")
end=s.index("else if(page==='theory')",start)
s=s[:start]+"if(page==='aim'){main.innerHTML=aimPage();if(globalThis.katex)katex.render(String.raw`\\theta \\mathrel{:=} \\theta - \\alpha \\nabla J(\\theta)`,document.querySelector('#aim-equation'),{displayMode:true,throwOnError:false});}\n"+s[end:]
s=s.replace("'Learning, one update at a time.'","'Theory'").replace("'Your route to the minimum.'","'Procedure'").replace("type==='pretest'?'Before you begin.':'Put your learning to the test.'","type==='pretest'?'Pretest':'Posttest'").replace("page==='demo'?'Watch the learning happen.':'Change a variable. Find a pattern.'","page==='demo'?'Demo':'Practice'")
for old,new in {'#b83465':'#8b1a1a','#d5cdd3':'#bdbdbd','#8c808c':'#555555','#f0e9ed':'#ededed','#be9caa':'#888888'}.items():s=s.replace(old,new)
s=s.replace('▶ Run experiment','Run experiment').replace('▶ Resume','Resume').replace('Ⅱ Pause','Pause').replace('▶ Run again','Run again').replace('↺ Reset','Reset')
p.write_text(s,encoding='utf-8')
